```typescript
import AsyncStorage from '@react-native-async-storage/async-storage';
import { Record, Product } from '../types';

const KEYS = {
  RECORDS: '@stall_records',
  PRODUCTS: '@stall_products',
};

// ========================================
// 通用 CRUD 辅助函数
// ========================================

async function getAll<T>(key: string): Promise<T[]> {
  const json = await AsyncStorage.getItem(key);
  if (!json) return [];
  return JSON.parse(json) as T[];
}

async function saveAll<T>(key: string, items: T[]): Promise<void> {
  await AsyncStorage.setItem(key, JSON.stringify(items));
}

// ========================================
// Record 操作
// ========================================

export async function getAllRecords(): Promise<Record[]> {
  return getAll<Record>(KEYS.RECORDS);
}

export async function getRecordById(id: string): Promise<Record | null> {
  const records = await getAllRecords();
  return records.find((r) => r.id === id) || null;
}

export async function addRecord(record: Record): Promise<void> {
  const records = await getAllRecords();
  records.unshift(record); // 最新的放前面
  await saveAll(KEYS.RECORDS, records);
}

export async function updateRecord(record: Record): Promise<void> {
  const records = await getAllRecords();
  const idx = records.findIndex((r) => r.id === record.id);
  if (idx !== -1) {
    records[idx] = record;
    await saveAll(KEYS.RECORDS, records);
  }
}

export async function deleteRecord(id: string): Promise<void> {
  const records = await getAllRecords();
  const filtered = records.filter((r) => r.id !== id);
  await saveAll(KEYS.RECORDS, filtered);
}

export async function getRecordsByDate(date: string): Promise<Record[]> {
  const records = await getAllRecords();
  return records.filter((r) => r.date === date);
}

export async function getRecordsByDateRange(
  startDate: string,
  endDate: string
): Promise<Record[]> {
  const records = await getAllRecords();
  return records.filter(
    (r) => r.date >= startDate && r.date <= endDate
  );
}

// ========================================
// Product 操作
// ========================================

export async function getAllProducts(): Promise<Product[]> {
  return getAll<Product>(KEYS.PRODUCTS);
}

export async function addProduct(product: Product): Promise<void> {
  const products = await getAllProducts();
  products.push(product);
  await saveAll(KEYS.PRODUCTS, products);
}

export async function updateProduct(product: Product): Promise<void> {
  const products = await getAllProducts();
  const idx = products.findIndex((p) => p.id === product.id);
  if (idx !== -1) {
    products[idx] = product;
    await saveAll(KEYS.PRODUCTS, products);
  }
}

export async function deleteProduct(id: string): Promise<void> {
  const products = await getAllProducts();
  const filtered = products.filter((p) => p.id !== id);
  await saveAll(KEYS.PRODUCTS, filtered);
}

// ========================================
// 导出 / 清空
// ========================================

export async function clearAllData(): Promise<void> {
  await AsyncStorage.multiRemove([KEYS.RECORDS, KEYS.PRODUCTS]);
}

export async function exportData(): Promise<string> {
  const records = await getAllRecords();
  const products = await getAllProducts();
  return JSON.stringify({ records, products, exportedAt: new Date().toISOString() }, null, 2);
}
```

