### File: `src/utils/analysis.ts`

```typescript
import { Record, AIAnalysis, RankingItem, SlowMovingItem, BusinessStatus, DailySummary } from '../types';

// ========================================
// 获取今日数据
// ========================================

function getToday(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function getWeekRange(): { start: string; end: string } {
  const now = new Date();
  const dayOfWeek = now.getDay();
  const diff = dayOfWeek === 0 ? 6 : dayOfWeek - 1; // 周一为一周开始
  const monday = new Date(now);
  monday.setDate(now.getDate() - diff);
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);
  return {
    start: formatDate(monday),
    end: formatDate(sunday),
  };
}

function getMonthRange(): { start: string; end: string } {
  const now = new Date();
  const first = new Date(now.getFullYear(), now.getMonth(), 1);
  const last = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  return {
    start: formatDate(first),
    end: formatDate(last),
  };
}

function formatDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

// ========================================
// 核心分析函数
// ========================================

export function computeRecord(
  income: number,
  cost: number,
  labor: number,
  quantity: number
): { profitPerItem: number; totalProfit: number; netProfit: number } {
  const totalProfit = income - cost;
  const profitPerItem = quantity > 0 ? totalProfit / quantity : 0;
  const netProfit = income - cost - labor;
  return {
    profitPerItem: Math.round(profitPerItem * 100) / 100,
    totalProfit: Math.round(totalProfit * 100) / 100,
    netProfit: Math.round(netProfit * 100) / 100,
  };
}

// ========================================
// AI 经营分析
// ========================================

export function getStatus(netProfit: number): BusinessStatus {
  if (netProfit >= 800) return '优秀';
  if (netProfit >= 200) return '一般';
  return '偏低';
}

export function generateAIAnalysis(records: Record[], date?: string): AIAnalysis {
  const targetDate = date || getToday();
  const dayRecords = records.filter((r) => r.date === targetDate);

  const totalNetProfit = dayRecords.reduce((sum, r) => sum + r.netProfit, 0);
  const totalIncome = dayRecords.reduce((sum, r) => sum + r.income, 0);
  const totalCost = dayRecords.reduce((sum, r) => sum + r.cost, 0);
  const totalLabor = dayRecords.reduce((sum, r) => sum + r.labor, 0);

  const status = getStatus(totalNetProfit);

  // 找利润最高商品
  let topProduct = '';
  let topProfit = -Infinity;
  const productProfits = new Map<string, number>();
  const productQuantities = new Map<string, number>();

  for (const r of dayRecords) {
    const current = productProfits.get(r.productName) || 0;
    productProfits.set(r.productName, current + r.totalProfit);
    const qty = productQuantities.get(r.productName) || 0;
    productQuantities.set(r.productName, qty + r.quantity);
  }

  for (const [name, profit] of productProfits) {
    if (profit > topProfit) {
      topProfit = profit;
      topProduct = name;
    }
  }

  // 滞销商品 (销量 <= 1)
  const slowMoving: string[] = [];
  for (const [name, qty] of productQuantities) {
    if (qty <= 1) {
      slowMoving.push(name);
    }
  }

  // ===== 生成建议 =====

  let summary = '';
  let topProductAdvice = '';
  let slowMovingAdvice = '';
  let profitAdvice = '';
  const nextActions: string[] = [];

  // 1. 经营状态总结
  if (status === '优秀') {
    summary = `今日经营状态优秀，净利润 ${totalNetProfit} 元，可以重点补货爆款商品。`;
  } else if (status === '偏低') {
    summary = `今日利润偏低，净利润 ${totalNetProfit} 元，建议提高客单价或优化组合销售。`;
  } else {
    summary = `今日经营状态一般，净利润 ${totalNetProfit} 元，收入 ${totalIncome} 元，成本 ${totalCost} 元，人工 ${totalLabor} 元。`;
  }

  // 2. 利润最高商品建议
  if (topProduct) {
    topProductAdvice = `${topProduct} 利润最高（${topProfit} 元），建议重点展示该商品，增加陈列面积。`;
    nextActions.push(`增加 ${topProduct} 的陈列和推广`);
  }

  // 3. 滞销商品建议
  if (slowMoving.length > 0) {
    const names = slowMoving.join('、');
    slowMovingAdvice = `${names} 销量偏低，建议减少库存或优化摆放位置。`;
    for (const name of slowMoving) {
      nextActions.push(`调整 ${name} 的定价或摆放位置`);
    }
  } else {
    slowMovingAdvice = '今日无滞销商品，库存管理良好。';
  }

  // 4. 利润优化建议
  if (totalNetProfit < 200 && totalNetProfit > 0) {
    profitAdvice = '今日净利润偏低，建议：① 提高客单价 ② 打包销售组合 ③ 增加高毛利商品比例。';
    nextActions.push('优化商品组合，提高客单价');
  } else if (totalNetProfit >= 800) {
    profitAdvice = '今日利润表现优秀，建议保持当前经营策略，关注客户复购率。';
  } else {
    profitAdvice = '利润平稳，建议尝试推出新品或限时促销提升客流。';
  }

  return {
    summary,
    status,
    topProductAdvice,
    slowMovingAdvice,
    profitAdvice,
    nextActions: nextActions.slice(0, 3), // 最多3条建议
  };
}

// ========================================
// 爆款排行榜
// ========================================

export function getRanking(records: Record[], date?: string): RankingItem[] {
  const targetDate = date || getToday();
  const dayRecords = records.filter((r) => r.date === targetDate);

  const productMap = new Map<string, { totalProfit: number; totalQuantity: number }>();

  for (const r of dayRecords) {
    const existing = productMap.get(r.productName);
    if (existing) {
      existing.totalProfit += r.totalProfit;
      existing.totalQuantity += r.quantity;
    } else {
      productMap.set(r.productName, {
        totalProfit: r.totalProfit,
        totalQuantity: r.quantity,
      });
    }
  }

  const rankings: RankingItem[] = [];
  for (const [productName, data] of productMap) {
    rankings.push({
      productName,
      totalProfit: Math.round(data.totalProfit * 100) / 100,
      totalQuantity: data.totalQuantity,
      rank: 0,
    });
  }

  // 按利润排序（降序）
  rankings.sort((a, b) => b.totalProfit - a.totalProfit);
  rankings.forEach((item, idx) => {
    item.rank = idx + 1;
  });

  return rankings;
}

// ========================================
// 滞销商品
// ========================================

export function getSlowMovingItems(records: Record[], date?: string): SlowMovingItem[] {
  const targetDate = date || getToday();
  const dayRecords = records.filter((r) => r.date === targetDate);
  return dayRecords
    .filter((r) => r.quantity <= 1)
    .map((r) => ({
      productName: r.productName,
      quantity: r.quantity,
      date: r.date,
    }));
}

// ========================================
// 趋势数据
// ========================================

export function getWeeklyTrend(records: Record[]): { labels: string[]; profits: number[] } {
  const range = getWeekRange();
  const dayRecords = records.filter(
    (r) => r.date >= range.start && r.date <= range.end
  );

  const dailyMap = new Map<string, number>();
  // 初始化一周7天
  const startDate = new Date(range.start);
  for (let i = 0; i < 7; i++) {
    const d = new Date(startDate);
    d.setDate(startDate.getDate() + i);
    const key = formatDate(d);
    dailyMap.set(key, 0);
  }

  for (const r of dayRecords) {
    const existing = dailyMap.get(r.date) || 0;
    dailyMap.set(r.date, existing + r.netProfit);
  }

  const labels: string[] = [];
  const profits: number[] = [];
  const weekDays = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];
  let idx = 0;
  for (const [date, profit] of dailyMap) {
    labels.push(weekDays[idx] || date.slice(5));
    profits.push(Math.round(profit * 100) / 100);
    idx++;
  }

  return { labels, profits };
}

export function getMonthlyTrend(records: Record[]): { labels: string[]; profits: number[] } {
  const range = getMonthRange();
  const monthRecords = records.filter(
    (r) => r.date >= range.start && r.date <= range.end
  );

  // 按日期分组
  const dailyMap = new Map<string, number>();
  for (const r of monthRecords) {
    const existing = dailyMap.get(r.date) || 0;
    dailyMap.set(r.date, existing + r.netProfit);
  }

  const sorted = [...dailyMap.entries()].sort((a, b) => a[0].localeCompare(b[0]));

  const labels: string[] = [];
  const profits: number[] = [];
  for (const [date, profit] of sorted) {
    // 只显示日
    labels.push(date.slice(5));
    profits.push(Math.round(profit * 100) / 100);
  }

  return { labels, profits };
}

// ========================================
// 首页摘要
// ========================================

export function getTodaySummary(records: Record[]): DailySummary {
  const today = getToday();
  const dayRecords = records.filter((r) => r.date === today);
  const totalNetProfit = dayRecords.reduce((sum, r) => sum + r.netProfit, 0);
  const totalSales = dayRecords.reduce((sum, r) => sum + r.income, 0);

  // 找爆款
  const rankings = getRanking(records, today);
  const topProduct = rankings.length > 0 ? rankings[0].productName : '暂无记录';
  const topProductProfit = rankings.length > 0 ? rankings[0].totalProfit : 0;

  return {
    date: today,
    netProfit: Math.round(totalNetProfit * 100) / 100,
    status: getStatus(totalNetProfit),
    topProduct,
    topProductProfit,
    totalSales: Math.round(totalSales * 100) / 100,
    recordCount: dayRecords.length,
  };
}

export function getToday(): string {
  return getToday();
}
```

