import React from 'react';
import { View, Text } from 'react-native';

interface StatCardProps {
  title: string;
  value: string | number;
  subtitle?: string;
  color?: string;
  icon?: string;
}

export default function StatCard({ title, value, subtitle, color = '#C43A31' }: StatCardProps) {
  return (
    <View
      style={{
        backgroundColor: '#FFFFFF',
        borderRadius: 16,
        padding: 16,
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.06,
        shadowRadius: 8,
        elevation: 3,
        borderLeftWidth: 3,
        borderLeftColor: color,
      }}
    >
      <Text style={{ fontSize: 13, color: '#8B8B8B', marginBottom: 4 }}>{title}</Text>
      <Text style={{ fontSize: 28, fontWeight: '700', color: '#2D2D2D' }}>
        {typeof value === 'number' ? `¥${value.toLocaleString()}` : value}
      </Text>
      {subtitle && (
        <Text style={{ fontSize: 12, color: '#B0B0B0', marginTop: 4 }}>{subtitle}</Text>
      )}
    </View>
  );
}
