function generateId(): string {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
}

export default function RecordScreen() {
  const [records, setRecords] = useState<Record[]>([]);
  const [refreshing, setRefreshing] = useState(false);

  // 表单状态
  const [modalVisible, setModalVisible] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [date, setDate] = useState(getToday());
  const [income, setIncome] = useState('');
  const [cost, setCost] = useState('');
  const [labor, setLabor] = useState('');
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');

  const loadData = useCallback(async () => {
    const allRecords = await getAllRecords();
    setRecords(allRecords);
  }, []);

  useFocusEffect(
    useCallback(() => {
      loadData();
    }, [loadData])
  );

  const resetForm = () => {
    setEditingId(null);
    setDate(getToday());
    setIncome('');
    setCost('');
    setLabor('');
    setProductName('');
    setQuantity('');
  };

  const openEdit = (record: Record) => {
    setEditingId(record.id);
    setDate(record.date);
    setIncome(String(record.income));
    setCost(String(record.cost));
    setLabor(String(record.labor));
    setProductName(record.productName);
    setQuantity(String(record.quantity));
    setModalVisible(true);
  };

  const handleDelete = (id: string) => {
    Alert.alert('确认删除', '删除后无法恢复', [
      { text: '取消', style: 'cancel' },
      {
        text: '删除',
        style: 'destructive',
        onPress: async () => {
          await deleteRecord(id);
          await loadData();
        },
      },
    ]);
  };

  const handleSubmit = async () => {
    // 校验
    if (!productName.trim()) {
      Alert.alert('提示', '请输入商品名称');
      return;
    }
    const incomeNum = parseFloat(income) || 0;
    const costNum = parseFloat(cost) || 0;
    const laborNum = parseFloat(labor) || 0;
    const quantityNum = parseInt(quantity) || 0;

    if (incomeNum <= 0) {
      Alert.alert('提示', '请输入有效收入');
      return;
    }

    const computed = computeRecord(incomeNum, costNum, laborNum, quantityNum);

    const record: Record = {
      id: editingId || generateId(),
      date,
      income: incomeNum,
      cost: costNum,
      labor: laborNum,
      productName: productName.trim(),
      quantity: quantityNum,
      profitPerItem: computed.profitPerItem,
      totalProfit: computed.totalProfit,
      netProfit: computed.netProfit,
      createdAt: editingId ? new Date().toISOString() : new Date().toISOString(),
    };

    if (editingId) {
      await updateRecord(record);
    } else {
      await addRecord(record);
    }

    resetForm();
    setModalVisible(false);
    await loadData();
  };

  const onRefresh = async () => {
    setRefreshing(true);
    await loadData();
    setRefreshing(false);
  };

  // 按日期分组显示
  const groupedRecords: { [date: string]: Record[] } = {};
  for (const r of records) {
    if (!groupedRecords[r.date]) groupedRecords[r.date] = [];
    groupedRecords[r.date].push(r);
  }
  const sortedDates = Object.keys(groupedRecords).sort((a, b) => b.localeCompare(a));

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: '#FFF8F0' }}>
      <View style={{ flex: 1 }}>
        {/* 顶部 */}
