              shadowOffset: { width: 0, height: 4 },
              shadowOpacity: 0.3,
              shadowRadius: 8,
              elevation: 4,
            }}
          >
            <Text style={{ fontSize: 24, color: '#FFFFFF' }}>+</Text>
          </TouchableOpacity>
        </View>

        {/* 记录列表 */}
        <ScrollView
          contentContainerStyle={{ padding: 16, paddingBottom: 32 }}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
        >
          {records.length === 0 ? (
            <EmptyState
              icon="📝"
              title="还没有记账记录"
              subtitle="点击右上角 + 号开始记录"
            />
          ) : (
            sortedDates.map((dateKey) => {
              const dayRecords = groupedRecords[dateKey];
              const dayProfit = dayRecords.reduce((s, r) => s + r.netProfit, 0);
              return (
                <View key={dateKey} style={{ marginBottom: 16 }}>
                  <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginBottom: 8 }}>
                    <Text style={{ fontSize: 14, fontWeight: '600', color: '#8B8B8B' }}>{dateKey}</Text>
