import React, { useState, useCallback } from 'react';
import { View, Text, ScrollView, TouchableOpacity, RefreshControl } from 'react-native';
import { useFocusEffect } from '@react-navigation/native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { getAllRecords } from '../utils/storage';
import {
  generateAIAnalysis,
  getRanking,
  getSlowMovingItems,
  getWeeklyTrend,
  getMonthlyTrend,
} from '../utils/analysis';
import { Record, AIAnalysis, RankingItem, SlowMovingItem } from '../types';
import TrendChart from '../components/TrendChart';
import RankingList from '../components/RankingList';
import SlowMovingAlert from '../components/SlowMovingAlert';
import AIAdvice from '../components/AIAdvice';
import EmptyState from '../components/EmptyState';

type ChartPeriod = '周' | '月';

export default function AnalysisScreen() {
  const [records, setRecords] = useState<Record[]>([]);
  const [analysis, setAnalysis] = useState<AIAnalysis | null>(null);
  const [rankings, setRankings] = useState<RankingItem[]>([]);
  const [slowMoving, setSlowMoving] = useState<SlowMovingItem[]>([]);
  const [period, setPeriod] = useState<ChartPeriod>('周');
  const [refreshing, setRefreshing] = useState(false);

  const loadData = useCallback(async () => {
    const allRecords = await getAllRecords();
    setRecords(allRecords);

    const ai = generateAIAnalysis(allRecords);
    setAnalysis(ai);

    const ranking = getRanking(allRecords);
    setRankings(ranking);

    const slow = getSlowMovingItems(allRecords);
    setSlowMoving(slow);
  }, []);

  useFocusEffect(
    useCallback(() => {
      loadData();
    }, [loadData])
  );

  const trendData = period === '周' ? getWeeklyTrend(records) : getMonthlyTrend(records);

  const onRefresh = async () => {
    setRefreshing(true);
    await loadData();
    setRefreshing(false);
  };

  return (
    <SafeAreaView style={{ flex: 1, backgroundColor: '#FFF8F0' }}>
      <ScrollView
        contentContainerStyle={{ padding: 16, paddingBottom: 32 }}
        refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
      >
        <Text style={{ fontSize: 24, fontWeight: '700', color: '#2D2D2D', marginBottom: 16 }}>
          经营分析
        </Text>

        {/* 趋势图 */}
        <View style={{ marginBottom: 16 }}>
          {/* 周期切换 */}
          <View style={{ flexDirection: 'row', marginBottom: 12 }}>
            {(['周', '月'] as ChartPeriod[]).map((p) => (
              <TouchableOpacity
                key={p}
                onPress={() => setPeriod(p)}
                style={{
                  paddingHorizontal: 16,
                  paddingVertical: 8,
                  borderRadius: 20,
                  backgroundColor: period === p ? '#C43A31' : '#F0F0F0',
                  marginRight: 8,
                }}
              >
                <Text
                  style={{
                    fontSize: 13,
                    fontWeight: '600',
                    color: period === p ? '#FFFFFF' : '#6B6B6B',
                  }}
                >
                  {p}趋势
                </Text>
              </TouchableOpacity>
            ))}
          </View>
          <TrendChart labels={trendData.labels} profits={trendData.profits} period={period} />
        </View>

        {/* 爆款排行榜 */}
        <View style={{ marginBottom: 16 }}>
          <RankingList items={rankings} />
        </View>

        {/* 滞销提醒 */}
        <View style={{ marginBottom: 16 }}>
          <SlowMovingAlert items={slowMoving} />
        </View>

        {/* AI 经营建议 */}
        {analysis && <AIAdvice analysis={analysis} />}

        {records.length === 0 && (
          <EmptyState
            icon="📊"
            title="暂无数据"
            subtitle="去记账页添加记录后，这里将展示分析结果"
          />
        )}
      </ScrollView>
    </SafeAreaView>
  );
}
