              },
              tabBarLabelStyle: {
                fontSize: 11,
                fontWeight: '600',
              },
            })}
          >
            <Tab.Screen
              name="Home"
              component={HomeScreen}
              options={{ tabBarLabel: '首页' }}
            />
            <Tab.Screen
              name="Record"
              component={RecordScreen}
              options={{ tabBarLabel: '记账' }}
            />
            <Tab.Screen
              name="Analysis"
              component={AnalysisScreen}
              options={{ tabBarLabel: '分析' }}
            />
            <Tab.Screen
              name="Product"
              component={ProductScreen}
              options={{ tabBarLabel: '商品' }}
            />
          </Tab.Navigator>
        </NavigationContainer>
      </PaperProvider>
